script:
// Task review workflow on the Task form:
// Submit For Review -> Approve / Request Changes -> Reopen.
// Backend: infintrix_atlas.api.task_review (permissions enforced server-side).
const TASK_REVIEW_API = "infintrix_atlas.api.task_review";

const TASK_REOPEN_TYPES = [
	"Client Feedback",
	"Bug Found",
	"QA Failure",
	"Requirement Missed",
	"Change Request",
	"Other",
];

frappe.ui.form.on("Task", {
	refresh(frm) {
		// Logs are written only by the review API. Lock rows instead of setting the
		// table read_only: Frappe hides empty read-only fields, which hid the tab.
		["custom_task_review_logs", "custom_task_reopen_logs"].forEach((f) => {
			const field = frm.fields_dict[f];
			if (!field) return;
			frm.set_df_property(f, "cannot_add_rows", 1);
			frm.set_df_property(f, "cannot_delete_rows", 1);
			field.grid.docfields.forEach((df) =>
				field.grid.update_docfield_property(df.fieldname, "read_only", 1)
			);
		});

		if (frm.is_new() || frm.is_dirty()) return;

		const docname = frm.doc.name;
		frappe
			.call(`${TASK_REVIEW_API}.get_review_actions`, { task_name: docname })
			.then((r) => {
				// The form may have moved on to another doc while the call was in flight.
				if (frm.doc.name !== docname) return;
				const res = r.message || {};
				const actions = res.actions || [];
				const group = __("Review");
				const done = () => frm.reload_doc();

				if (frm.doc.status === "Pending Review" && frm.doc.custom_reviewer) {
					frm.dashboard.set_headline(
						__("Waiting for review by {0}", [
							`<b>${frappe.utils.escape_html(frappe.user.full_name(frm.doc.custom_reviewer))}</b>`,
						]),
						"yellow"
					);
				}

				if (actions.includes("submit_for_review")) {
					frm.add_custom_button(__("Submit For Review"), () =>
						task_review_dialog(frm, {
							title: __("Submit For Review"),
							label: __("Submit"),
							method: "submit_for_review",
							fields: [
								{
									fieldname: "reviewer",
									label: __("Reviewer"),
									fieldtype: "Link",
									options: "User",
									reqd: 1,
									// Pre-fill the previous reviewer when resubmitting after changes.
									default: res.reviewer || "",
									description: __("Pick a project member or a project manager. You and the task's assignee cannot review it. The reviewer is notified to approve or request changes."),
									get_query: () => ({
										query: `${TASK_REVIEW_API}.reviewer_query`,
										filters: { task: docname },
									}),
								},
							],
							args: (v) => ({ task_name: docname, reviewer: v.reviewer }),
						}), group);
				}
				if (actions.includes("approve")) {
					frm.add_custom_button(__("Approve"), () =>
						task_review_dialog(frm, {
							title: __("Approve Task"),
							label: __("Approve"),
							method: "approve_task",
							fields: [{ fieldname: "comments", label: __("Comments"), fieldtype: "Small Text", description: __("Optional") }],
							args: (v) => ({ task_name: docname, comments: v.comments || null }),
						}), group);
				}
				if (actions.includes("request_changes")) {
					frm.add_custom_button(__("Request Changes"), () =>
						task_review_dialog(frm, {
							title: __("Request Changes"),
							label: __("Request Changes"),
							method: "request_changes",
							fields: [{ fieldname: "comments", label: __("Comments"), fieldtype: "Small Text", reqd: 1, description: __("Describe what needs to be changed.") }],
							args: (v) => ({ task_name: docname, comments: v.comments }),
						}), group);
				}
				if (actions.includes("reopen")) {
					frm.add_custom_button(__("Reopen Task"), () =>
						task_review_dialog(frm, {
							title: __("Reopen Task"),
							label: __("Reopen"),
							method: "reopen_task",
							fields: [
								{ fieldname: "reopen_type", label: __("Reopen Type"), fieldtype: "Select", options: TASK_REOPEN_TYPES.join("\n"), default: "Bug Found", reqd: 1 },
								{ fieldname: "reason", label: __("Reason"), fieldtype: "Small Text", reqd: 1 },
							],
							args: (v) => ({ task_name: docname, reason: v.reason, reopen_type: v.reopen_type }),
						}), group);
				}

				if (actions.length) frm.page.set_inner_btn_group_as_primary(group);
			});
	},
});

function task_review_call(frm, method, args, on_done, dialog) {
	return frappe.call({
		method: `${TASK_REVIEW_API}.${method}`,
		args,
		freeze: true,
		callback: (r) => {
			const res = r.message || {};
			if (dialog) dialog.hide();
			frappe.show_alert({ message: res.message || __("Updated"), indicator: "green" });
			on_done && on_done();
		},
	});
}

function task_review_dialog(frm, opts) {
	const d = new frappe.ui.Dialog({
		title: opts.title,
		fields: opts.fields,
		primary_action_label: opts.label,
		primary_action: (values) =>
			task_review_call(frm, opts.method, opts.args(values), () => frm.reload_doc(), d),
	});
	d.show();
}
